    await page.waitForTimeout\(1000\);

    await page.getByRole\("link", { name: "Observabilidade" }\).click\(\);
    await expect\(page\).toHaveURL\(/\\/observability/\);
    await page.waitForTimeout\(1000\);

    await page.getByRole\("link", { name: "Logs" }\).click\(\);
